// @FIGURE_CODE_BEGIN
// ELEMENT SPEC
// axes        → thin cylinders + cone heads, #444; z up 5.4, y right 4.2, x 3.2
// top body    → LatheGeometry teardrop, #a8cce0 phong, tip at O, height 2.2
// orange band → LatheGeometry ring (widest third), #f0b44c
// stem        → CylinderGeometry r0.25 h0.9, #7fb3d0, along tilted axis
// green loop  → TorusGeometry r0.55 + cone head, #5a9a3c (spin sense ω)
// r arrow     → black arrow O→CM (axis dist 1.5), CM = crossed boxes (X)
// Mg arrow    → red #cc2222, always world-vertical down from CM, len 1.05
// τ arrow     → orange #e8862a, from CM toward -x (r×Mg), len 0.6·τ
// L arrow     → orange, along axis from CM, fixed len 3.2, tip reaches circle
// dashed circ → LineDashedMaterial circle, center on z-axis, radius |r+L|sinθ
// radial arr  → orange, z-axis → L tip, labeled L sinθ
// dL arrow    → orange, tangential at L tip, len ∝ τ
// dφ wedge    → small arc at circle center between successive radials
// ωp arrow    → black arc + cone head at upper-left rim of circle
// θ arc       → thin arc at O between z-axis and tilt axis

const DEG = Math.PI / 180;
const V3 = (x, y, z) => new THREE.Vector3(x, y, z);
let theta = 30 * DEG, tauMag = 1, phi = 0, playing = false;
const L_LEN = 3.2, CM_D = 1.5, TIP_D = CM_D + L_LEN; // distances along axis

/* ── lights ── */
scene.add(new THREE.AmbientLight(0xffffff, 0.75));
const _dl = new THREE.DirectionalLight(0xffffff, 0.9);
_dl.position.set(4, 6, 8); scene.add(_dl);

/* ── arrow helper (shaft + cone along dir) ── */
function makeArrow(dir, len, color, shaftR = 0.035, headLen = 0.17, headR = 0.1) {
  const g = new THREE.Group();
  const m = new THREE.MeshBasicMaterial({ color });
  const sl = Math.max(len - headLen, 0.02);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, sl, 10), m);
  shaft.position.y = sl / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 12), m);
  head.position.y = sl + headLen / 2;
  g.add(shaft, head);
  g.quaternion.setFromUnitVectors(V3(0, 1, 0), dir.clone().normalize());
  return g;
}

/* ── axes ── */
function makeAxis(dir, len) {
  const g = new THREE.Group();
  const m = new THREE.MeshBasicMaterial({ color: 0x444444 });
  const c = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, len, 8), m);
  c.position.y = len / 2;
  const h = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.16, 10), m);
  h.position.y = len + 0.08;
  g.add(c, h);
  g.quaternion.setFromUnitVectors(V3(0, 1, 0), dir.clone().normalize());
  scene.add(g);
}
makeAxis(V3(0, 0, 1), 5.3);
makeAxis(V3(0, 1, 0), 4.2);
makeAxis(V3(1, 0, 0), 3.2);

/* ── precession & tilt groups ── */
const P = new THREE.Group(); scene.add(P);      // rotates about z (precession)
const T = new THREE.Group(); P.add(T);          // tilted by θ about x (toward +y)

/* ── top body ── */
const prof = [[0.02, 0], [0.30, 0.18], [0.55, 0.45], [0.85, 0.8], [1.05, 1.15],
[1.10, 1.45], [1.02, 1.7], [0.80, 1.95], [0.55, 2.12], [0.42, 2.2]];
function radiusAt(h) {
  for (let i = 0; i < prof.length - 1; i++) {
    const [r0, h0] = prof[i], [r1, h1] = prof[i + 1];
    if (h >= h0 && h <= h1) return r0 + (r1 - r0) * (h - h0) / (h1 - h0);
  }
  return 0.02;
}
const bodyMesh = new THREE.Mesh(
  new THREE.LatheGeometry(prof.map(p => new THREE.Vector2(p[0], p[1])), 48),
  new THREE.MeshPhongMaterial({ color: 0xa8cce0, shininess: 45, transparent: true, opacity: 0.92 })
);
T.add(bodyMesh);
registerInteractive(bodyMesh, {
  title: 'Spinning top',
  body: 'Gravity Mg pulls down on the center of mass, producing torque τ = r × Mg. Because τ is perpendicular to L, it changes only the direction of L, so the top precesses instead of falling.'
});

const bandPts = [];
for (let h = 0.95; h <= 1.701; h += 0.05) bandPts.push(new THREE.Vector2(radiusAt(h) + 0.015, h));
const band = new THREE.Mesh(
  new THREE.LatheGeometry(bandPts, 48),
  new THREE.MeshPhongMaterial({ color: 0xf0b44c, shininess: 35, side: THREE.DoubleSide })
);
T.add(band);

const stem = new THREE.Mesh(
  new THREE.CylinderGeometry(0.25, 0.25, 0.9, 24),
  new THREE.MeshPhongMaterial({ color: 0x7fb3d0, shininess: 60, transparent: true, opacity: 0.9 })
);
stem.position.y = 2.65; T.add(stem);

/* ── r arrow + CM cross ── */
const rArr = makeArrow(V3(0, 1, 0), CM_D, 0x111111, 0.045, 0.16, 0.11);
T.add(rArr);
registerInteractive(rArr, { title: 'r', body: 'Position vector from the pivot O to the center of mass.' });
const cmX = new THREE.Group();
const bm = new THREE.MeshBasicMaterial({ color: 0x111111 });
const b1 = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.035, 0.035), bm);
const b2 = b1.clone(); b2.rotation.y = Math.PI / 2; b1.rotation.y = Math.PI / 4; b2.rotation.y = -Math.PI / 4;
cmX.add(b1, b2); cmX.position.y = CM_D; T.add(cmX);

/* ── L arrow (fixed length) ── */
const lArr = makeArrow(V3(0, 1, 0), L_LEN, 0xe8862a, 0.042, 0.24, 0.13);
lArr.position.y = CM_D; T.add(lArr);
registerInteractive(lArr, {
  title: 'L — angular momentum',
  body: 'Spin angular momentum along the symmetry axis. Its magnitude is constant; torque only swings its tip around the dashed precession circle.'
});

/* ── green spin loop around stem ── */
const loopG = new THREE.Group();
const tor = new THREE.Mesh(new THREE.TorusGeometry(0.55, 0.038, 10, 48),
  new THREE.MeshBasicMaterial({ color: 0x5a9a3c }));
tor.rotation.x = Math.PI / 2;
const loopHead = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.2, 10),
  new THREE.MeshBasicMaterial({ color: 0x5a9a3c }));
loopHead.position.set(0.55, 0, 0);
loopHead.quaternion.setFromUnitVectors(V3(0, 1, 0), V3(0, 0, 1));
loopG.add(tor, loopHead);
loopG.position.y = 2.35; T.add(loopG);
registerInteractive(loopG, { title: 'ω — spin', body: 'The top spins rapidly about its own symmetry axis; this is what gives it angular momentum L.' });

/* ── reactive geometry holders ── */
const dynScene = [];   // θ-arc, dashed circle, ωp arc (don't rotate with φ)
const dynP = [];       // Mg, τ, radial, dL, wedge (children of P, rotate with φ)
const S = { cmL: new V3(), tipL: new V3(), R: 1, H: 3, dphiPos: new V3(), tauLen: 1, dLLen: 1 };

/* ── labels (created once, positions synced) ── */
const lblO = addLabel('<b>O</b>', V3(-0.12, -0.22, 0), { offset: [-8, 8] });
addLabel('x', V3(3.35, 0, 0), { bold: true });
addLabel('y', V3(0, 4.4, 0), { bold: true });
addLabel('z', V3(0, 0, 5.5), { bold: true });
const lblTheta = addLabel('θ', V3(0, 0, 0), { fontSize: '14px' });
const lblCM = addLabel('CM', V3(), { fontSize: '12px', bold: true });
const lblR = addLabel('<b>r</b>', V3(), { color: '#111' });
const lblMg = addLabel('<i>M</i>g&#8407;', V3(), { color: '#cc2222' });
const lblTau = addLabel('τ&#8407;', V3(), { color: '#e8862a', bold: true });
const lblL = addLabel('<b>L</b>&#8407;', V3(), { color: '#e8862a' });
const lblLsin = addLabel('L sinθ', V3(), { color: '#b06000', fontSize: '12px' });
const lblDL = addLabel('dL&#8407; = τ&#8407;dt', V3(), { color: '#e8862a', fontSize: '12px' });
const lblDphi = addLabel('dφ', V3(), { fontSize: '12px' });
const lblOm = addLabel('ω', V3(), { color: '#3f7a2a', bold: true });
const lblOmp = addLabel('ω<sub>p</sub>', V3(), { fontSize: '14px', bold: true });
const lblTauEq = addLabel('τ&#8407; = r&#8407; × Mg&#8407;', V3(2.5, -1.5, 0.9), { fontSize: '13px', bold: true });

/* ── leader curve: τ = r × Mg label → τ arrow (rebuilt per frame) ── */
const LEAD_N = 12;
const leadGeom = new THREE.BufferGeometry();
leadGeom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(LEAD_N * 3), 3));
const leadLine = new THREE.Line(leadGeom, new THREE.LineBasicMaterial({ color: 0x333333 }));
scene.add(leadLine);

/* ── rebuild all θ / τ dependent geometry ── */
function rebuild() {
  T.rotation.x = -theta;                       // tilt axis toward +y
  for (const o of dynScene) { scene.remove(o); _disposeObject(o); }
  for (const o of dynP) { P.remove(o); _disposeObject(o); }
  dynScene.length = 0; dynP.length = 0;

  const H = TIP_D * Math.cos(theta), R = TIP_D * Math.sin(theta);
  S.H = H; S.R = R;
  S.cmL.set(0, CM_D * Math.sin(theta), CM_D * Math.cos(theta));
  S.tipL.set(0, R, H);
  S.tauLen = 0.6 * tauMag; S.dLLen = 0.5 * tauMag;

  // θ arc at O
  const thPts = [];
  for (let a = 0; a <= theta + 1e-4; a += theta / 24) thPts.push(V3(0, 1.15 * Math.sin(a), 1.15 * Math.cos(a)));
  const thArc = new THREE.Line(new THREE.BufferGeometry().setFromPoints(thPts),
    new THREE.LineBasicMaterial({ color: 0x333333 }));
  scene.add(thArc); dynScene.push(thArc);
  lblTheta.pos.set(0, 1.45 * Math.sin(theta / 2) - 0.12, 1.45 * Math.cos(theta / 2));

  // dashed precession circle
  const cPts = [];
  for (let t = 0; t <= Math.PI * 2 + 1e-4; t += Math.PI / 72) cPts.push(V3(R * Math.cos(t), R * Math.sin(t), H));
  const circ = new THREE.Line(new THREE.BufferGeometry().setFromPoints(cPts),
    new THREE.LineDashedMaterial({ color: 0x555555, dashSize: 0.18, gapSize: 0.12 }));
  circ.computeLineDistances();
  scene.add(circ); dynScene.push(circ);

  // ωp curved arrow at upper-left rim (precession: +y toward -x, i.e. growing xy-angle)
  const a0 = 112 * DEG, a1 = 196 * DEG;
  const wPts = [];
  for (let a = a0; a <= a1; a += (a1 - a0) / 24) wPts.push(V3(R * Math.cos(a), R * Math.sin(a), H + 0.04));
  const omLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints(wPts),
    new THREE.LineBasicMaterial({ color: 0x111111 }));
  const omHead = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.2, 10),
    new THREE.MeshBasicMaterial({ color: 0x111111 }));
  omHead.position.copy(wPts[wPts.length - 1]);
  omHead.quaternion.setFromUnitVectors(V3(0, 1, 0), V3(-Math.sin(a1), Math.cos(a1), 0));
  scene.add(omLine, omHead); dynScene.push(omLine, omHead);
  lblOmp.pos.set((R + 0.5) * Math.cos(152 * DEG), (R + 0.5) * Math.sin(152 * DEG), H + 0.15);

  // Mg (world-vertical; child of P so it follows CM around)
  const mg = makeArrow(V3(0, 0, -1), 1.05, 0xcc2222, 0.04, 0.18, 0.11);
  mg.position.copy(S.cmL); P.add(mg); dynP.push(mg);
  registerInteractive(mg, { title: 'Mg', body: 'Gravity acts straight down on the center of mass — it stays vertical while the top precesses.' });

  // τ = r × Mg (points along -x in P-frame at φ=0)
  const tau = makeArrow(V3(-1, 0, 0), S.tauLen, 0xe8862a, 0.042, 0.17, 0.11);
  tau.position.copy(S.cmL); P.add(tau); dynP.push(tau);
  registerInteractive(tau, { title: 'τ = r × Mg', body: 'Torque is perpendicular to both r and Mg — hence perpendicular to L, so dL is purely tangential.' });

