/* ── rebuild all θ / τ dependent geometry ── */
function rebuild() {
  T.rotation.x = -theta;                       // tilt axis toward +y
  for (const o of dynScene) { scene.remove(o); _disposeObject(o); }
  for (const o of dynP) { P.remove(o); _disposeObject(o); }
  dynScene.length = 0; dynP.length = 0;

  const H = TIP_D * Math.cos(theta), R = TIP_D * Math.sin(theta);
  S.H = H; S.R = R;
  S.cmL.set(0, CM_D * Math.sin(theta), CM_D * Math.cos(theta));
  S.tipL.set(0, R, H);
  S.tauLen = 0.6 * tauMag; S.dLLen = 0.5 * tauMag;

  // θ arc at O
  const thPts = [];
  for (let a = 0; a <= theta + 1e-4; a += theta / 24) thPts.push(V3(0, 1.15 * Math.sin(a), 1.15 * Math.cos(a)));
  const thArc = new THREE.Line(new THREE.BufferGeometry().setFromPoints(thPts),
    new THREE.LineBasicMaterial({ color: 0x333333 }));
  scene.add(thArc); dynScene.push(thArc);
  lblTheta.pos.set(0, 1.45 * Math.sin(theta / 2) - 0.12, 1.45 * Math.cos(theta / 2));

  // dashed precession circle
  const cPts = [];
  for (let t = 0; t <= Math.PI * 2 + 1e-4; t += Math.PI / 72) cPts.push(V3(R * Math.cos(t), R * Math.sin(t), H));
  const circ = new THREE.Line(new THREE.BufferGeometry().setFromPoints(cPts),
    new THREE.LineDashedMaterial({ color: 0x555555, dashSize: 0.18, gapSize: 0.12 }));
  circ.computeLineDistances();
  scene.add(circ); dynScene.push(circ);

  // ωp curved arrow at upper-left rim (precession: +y toward -x, i.e. growing xy-angle)
  const a0 = 112 * DEG, a1 = 196 * DEG;
  const wPts = [];
  for (let a = a0; a <= a1; a += (a1 - a0) / 24) wPts.push(V3(R * Math.cos(a), R * Math.sin(a), H + 0.04));
  const omLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints(wPts),
    new THREE.LineBasicMaterial({ color: 0x111111 }));
  const omHead = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.2, 10),
    new THREE.MeshBasicMaterial({ color: 0x111111 }));
  omHead.position.copy(wPts[wPts.length - 1]);
  omHead.quaternion.setFromUnitVectors(V3(0, 1, 0), V3(-Math.sin(a1), Math.cos(a1), 0));
  scene.add(omLine, omHead); dynScene.push(omLine, omHead);
  lblOmp.pos.set((R + 0.5) * Math.cos(152 * DEG), (R + 0.5) * Math.sin(152 * DEG), H + 0.15);

  // Mg (world-vertical; child of P so it follows CM around)
  const mg = makeArrow(V3(0, 0, -1), 1.05, 0xcc2222, 0.04, 0.18, 0.11);
  mg.position.copy(S.cmL); P.add(mg); dynP.push(mg);
  registerInteractive(mg, { title: 'Mg', body: 'Gravity acts straight down on the center of mass — it stays vertical while the top precesses.' });

  // τ = r × Mg (points along -x in P-frame at φ=0)
  const tau = makeArrow(V3(-1, 0, 0), S.tauLen, 0xe8862a, 0.042, 0.17, 0.11);
  tau.position.copy(S.cmL); P.add(tau); dynP.push(tau);
  registerInteractive(tau, { title: 'τ = r × Mg', body: 'Torque is perpendicular to both r and Mg — hence perpendicular to L, so dL is purely tangential.' });

  // radial L sinθ arrow (z-axis → L tip, inside circle)
  const rad = makeArrow(V3(0, 1, 0), R, 0xe8862a, 0.03, 0.15, 0.1);
  rad.position.set(0, 0, H); P.add(rad); dynP.push(rad);

  // dL tangential arrow at L tip
  const dl2 = makeArrow(V3(-1, 0, 0), S.dLLen, 0xe8862a, 0.035, 0.14, 0.1);
  dl2.position.copy(S.tipL); P.add(dl2); dynP.push(dl2);
  registerInteractive(dl2, { title: 'dL = τ dt', body: 'Each small step of L lies along the tangent, so |L| never changes — L only rotates, sweeping the dashed circle.' });

  // dφ wedge at circle center (current vs next radial)
  const wR = Math.min(0.9, R * 0.45);
  const w2 = [];
  for (let a = 90 * DEG; a <= 118 * DEG; a += 2 * DEG) w2.push(V3(wR * Math.cos(a), wR * Math.sin(a), H));
  const wedge = new THREE.Line(new THREE.BufferGeometry().setFromPoints(w2),
    new THREE.LineBasicMaterial({ color: 0x333333 }));
  P.add(wedge); dynP.push(wedge);
  S.dphiPos.set((wR + 0.32) * Math.cos(104 * DEG), (wR + 0.32) * Math.sin(104 * DEG), H);
}
