function tick() {
  requestAnimationFrame(tick);
  const dt = Math.min(clock.getDelta(), 0.05);
  if (playing) {
    phi += (tauMag / (L_LEN * Math.sin(theta))) * 0.9 * dt;  // ωp = τ/(L sinθ)
    P.rotation.z = phi;
