  lblLsin.pos.copy(_w.set(0, S.R * 0.45, S.H + 0.22).applyMatrix4(P.matrixWorld));
  lblDL.pos.copy(_w.set(-(S.dLLen + 0.35), S.R, S.H + 0.05).applyMatrix4(P.matrixWorld));
  lblDphi.pos.copy(_w.copy(S.dphiPos).applyMatrix4(P.matrixWorld));
  lblOm.pos.copy(T.localToWorld(V3(-0.62, 2.35, 0.25)));

