  _ctrl.lerpVectors(_a, _b, 0.5).add(V3(0, 0, -0.5));
  leadCurve.v0.copy(_a); leadCurve.v1.copy(_ctrl); leadCurve.v2.copy(_b);
  const arr = leadGeom.attributes.position.array;
  for (let i = 0; i < LEAD_N; i++) {
    const pt = leadCurve.getPoint(i / (LEAD_N - 1));
    arr[i * 3] = pt.x; arr[i * 3 + 1] = pt.y; arr[i * 3 + 2] = pt.z;
  }
  leadGeom.attributes.position.needsUpdate = true;
}
