// @FIGURE_CODE_BEGIN
// ELEMENT SPEC
// axes          → thin cylinders + cone heads, #444, overlay (drawn through body); z up 5.5, y right 3.7, x 2.8 (projects lower-left)
// top body      → LatheGeometry teardrop h2.2 rmax1.1, #a8cce0 translucent 0.55, tip at O; cap disc at h2.2
// orange band   → LatheGeometry shell h0.72→1.88 (broad painted stripe), #f0b44c opacity 0.9
// stem          → CylinderGeometry r0.25 h0.9, #7fb3d0, along tilted axis, centered at axis-dist 2.65
// green loop    → TorusGeometry r0.62 tube0.04 + cone head, #5a9a3c, around stem; spins about axis (sense ω)
// r arrow       → overlay black arrow O→CM (axis dist 1.5); CM = small X of two thin boxes on the axis
// Mg arrow      → overlay red #cc2222, world-vertical down from CM (child of P, dir (0,0,-1)), len 1.15
// τ arrow       → overlay orange #e8862a, from CM along local -x (= r×Mg dir), len 0.6·τ
// L arrow       → overlay orange, along axis from CM, fixed len 3.3, tip on the dashed circle
// dashed circle → 2 × LineDashedMaterial circles (R±0.1), center on z-axis, R=TIP_D sinθ, H=TIP_D cosθ
// radial arrow  → overlay orange, z-axis → L tip, labeled "L sinθ"
// dL arrow      → overlay orange, tangential at L tip (local -x), len 0.45·τ+0.15
// dφ wedge      → thin arc at circle center between current & next radial (child of P)
// ωp arrow      → TubeGeometry arc (200°→288°) + cone head, black, upper-left rim of circle
// θ arc         → overlay arc r1.02 at O in the y–z plane between z-axis and tilt axis
// leader        → QuadraticBezierCurve3 line from "τ = r × Mg" label to the τ arrow tip

const DEG = Math.PI / 180;
const V3 = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const UP = V3(0, 1, 0);
let theta = 30 * DEG, tauMag = 1, phi = 0, playing = false;
const L_LEN = 3.3, CM_D = 1.5, TIP_D = CM_D + L_LEN;

/* ── lights (for the Phong body) ── */
scene.add(new THREE.AmbientLight(0xffffff, 0.8));
const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(3, 5, 7);
scene.add(dirLight);

/* ── arrow builder: (re)fills a persistent group with shaft + cone along dir ── */
function buildArrow(group, dir, len, color, shaftR, headLen, headR, overlay) {
  while (group.children.length) {
    const c = group.children[0];
    group.remove(c);
    c.geometry.dispose();
    c.material.dispose();
  }
  const mat = new THREE.MeshBasicMaterial(overlay
    ? { color, transparent: true, opacity: 1, depthTest: false, depthWrite: false }
    : { color });
  const sl = Math.max(len - headLen, 0.02);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, sl, 12), mat);
  shaft.position.y = sl / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 14), mat);
  head.position.y = sl + headLen / 2;
  if (overlay) { shaft.renderOrder = 10; head.renderOrder = 10; }
  group.add(shaft, head);
  group.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  return group;
}

/* ── coordinate triad (overlay so z-axis shows through the body, as printed) ── */
function makeAxis(dir, len) {
  const g = new THREE.Group();
  const m = new THREE.MeshBasicMaterial({ color: 0x444444, transparent: true, opacity: 1, depthTest: false, depthWrite: false });
  const c = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, len, 8), m);
  c.position.y = len / 2;
  const h = new THREE.Mesh(new THREE.ConeGeometry(0.065, 0.18, 10), m);
  h.position.y = len + 0.09;
  c.renderOrder = 5; h.renderOrder = 5;
  g.add(c, h);
  g.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  scene.add(g);
}
makeAxis(V3(0, 0, 1), 5.5);
makeAxis(V3(0, 1, 0), 3.7);
makeAxis(V3(1, 0, 0), 2.8);

/* ── precession group P (rotates about z) and tilt group T (leans toward +y) ── */
const P = new THREE.Group(); scene.add(P);
const T = new THREE.Group(); P.add(T);

/* ── top body: lathe teardrop, tip at O ── */
const prof = [[0.02, 0], [0.28, 0.15], [0.5, 0.4], [0.72, 0.7], [0.95, 1.0], [1.08, 1.3],
[1.10, 1.5], [1.02, 1.7], [0.85, 1.9], [0.62, 2.05], [0.45, 2.15], [0.42, 2.2]];
function radiusAt(h) {
  for (let i = 0; i < prof.length - 1; i++) {
    const r0 = prof[i][0], h0 = prof[i][1], r1 = prof[i + 1][0], h1 = prof[i + 1][1];
    if (h >= h0 && h <= h1) return r0 + (r1 - r0) * (h - h0) / (h1 - h0);
  }
  return 0.02;
}
const bodyMesh = new THREE.Mesh(
  new THREE.LatheGeometry(prof.map(p => new THREE.Vector2(p[0], p[1])), 56),
  new THREE.MeshPhongMaterial({ color: 0xa8cce0, shininess: 40, transparent: true, opacity: 0.55, depthWrite: false, side: THREE.DoubleSide })
);
bodyMesh.renderOrder = 2;
T.add(bodyMesh);
registerInteractive(bodyMesh, {
  title: 'Spinning top',
  body: 'Gravity Mg pulls down on the center of mass, producing torque τ = r × Mg. Because τ is perpendicular to L, it changes only the direction of L, so the top precesses instead of falling.'
});

const capMesh = new THREE.Mesh(
  new THREE.CircleGeometry(0.42, 32),
  new THREE.MeshPhongMaterial({ color: 0x9cc2da, transparent: true, opacity: 0.7, depthWrite: false, side: THREE.DoubleSide })
);
capMesh.rotation.x = -Math.PI / 2;
capMesh.position.y = 2.2;
capMesh.renderOrder = 2;
T.add(capMesh);

/* broad painted orange stripe over the widest third */
const bandPts = [];
for (let h = 0.72; h <= 1.881; h += 0.04) bandPts.push(new THREE.Vector2(radiusAt(h) + 0.022, h));
const band = new THREE.Mesh(
  new THREE.LatheGeometry(bandPts, 56),
  new THREE.MeshPhongMaterial({ color: 0xf0b44c, shininess: 30, transparent: true, opacity: 0.9, depthWrite: false, side: THREE.DoubleSide })
);
band.renderOrder = 3;
T.add(band);

const stem = new THREE.Mesh(
  new THREE.CylinderGeometry(0.25, 0.25, 0.9, 24),
  new THREE.MeshPhongMaterial({ color: 0x7fb3d0, shininess: 60 })
);
stem.position.y = 2.65;
T.add(stem);

/* ── r arrow (static child of T) + CM cross ── */
const rG = new THREE.Group(); T.add(rG);
buildArrow(rG, V3(0, 1, 0), CM_D, 0x111111, 0.05, 0.18, 0.12, true);
registerInteractive(rG, { title: 'r', body: 'Position vector from the pivot O to the center of mass of the top.' });

const cmG = new THREE.Group();
const cmMat = new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true, opacity: 1, depthTest: false, depthWrite: false });
const cb1 = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.04, 0.04), cmMat);
