buildArrow(lG, V3(0, 1, 0), L_LEN, 0xe8862a, 0.045, 0.26, 0.13, true);
registerInteractive(lG, {
  title: 'L — angular momentum',
  body: 'Spin angular momentum along the symmetry axis. Its magnitude is constant; torque only swings its tip around the dashed precession circle.'
});

/* ── green spin loop around the stem (spun in tick) ── */
const loopG = new THREE.Group();
const tor = new THREE.Mesh(new THREE.TorusGeometry(0.62, 0.04, 10, 48),
  new THREE.MeshBasicMaterial({ color: 0x5a9a3c }));
tor.rotation.x = Math.PI / 2;
const loopHead = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.24, 10),
  new THREE.MeshBasicMaterial({ color: 0x5a9a3c }));
loopHead.position.set(0.62, 0, 0);
loopHead.quaternion.setFromUnitVectors(UP, V3(0, 0, -1)); // RHR sense matching L along +axis
loopG.add(tor, loopHead);
loopG.position.y = 2.42;
T.add(loopG);
registerInteractive(loopG, { title: 'ω — spin', body: 'The top spins rapidly about its own symmetry axis; this is what gives it angular momentum L.' });

/* ── persistent reactive arrow groups ── */
const mgG = new THREE.Group(); P.add(mgG);                 // stays world-vertical
const tauG = new THREE.Group(); tauG.position.y = CM_D; T.add(tauG);
const dlG = new THREE.Group(); dlG.position.y = TIP_D; T.add(dlG);
const radG = new THREE.Group(); P.add(radG);
registerInteractive(mgG, { title: 'Mg', body: 'Gravity acts straight down on the center of mass — it stays vertical while the top precesses.' });
registerInteractive(tauG, { title: 'τ = r × Mg', body: 'Torque is perpendicular to both r and Mg — hence perpendicular to L, so dL is purely tangential.' });
registerInteractive(dlG, { title: 'dL = τ dt', body: 'Each small step of L lies along the tangent, so |L| never changes — L only rotates, sweeping the dashed circle.' });

/* ── labels (positions synced in rebuild / tick) ── */
addLabel('<b>O</b>', V3(-0.1, -0.3, -0.05), { fontSize: '18px' });
addLabel('<b>x</b>', V3(3.08, 0, 0), { fontSize: '18px' });
addLabel('<b>y</b>', V3(0.05, 3.94, 0), { fontSize: '18px' });
addLabel('<b>z</b>', V3(0.06, 0, 5.74), { fontSize: '18px' });
const lblTheta = addLabel('θ', V3(), { fontSize: '19px', background: 'rgba(255,255,255,0.6)' });
const lblCM = addLabel('CM', V3(), { fontSize: '15px', bold: true, background: 'rgba(255,255,255,0.6)' });
const lblR = addLabel('<b>r</b>&#8407;', V3(), { fontSize: '19px', background: 'rgba(255,255,255,0.6)' });
const lblMg = addLabel('<i>M</i>g&#8407;', V3(), { color: '#cc2222', fontSize: '19px', background: 'rgba(255,255,255,0.6)' });
const lblTau = addLabel('τ&#8407;', V3(), { color: '#e8862a', bold: true, fontSize: '19px' });
const lblL = addLabel('L&#8407;', V3(), { color: '#e8862a', bold: true, fontSize: '19px' });
const lblLsin = addLabel('L sinθ', V3(), { color: '#b06000', fontSize: '16px' });
const lblDL = addLabel('dL&#8407; = τ&#8407;dt', V3(), { color: '#e8862a', fontSize: '16px' });
const lblDphi = addLabel('dφ', V3(), { fontSize: '16px' });
const lblOm = addLabel('ω', V3(), { color: '#3f7a2a', bold: true, fontSize: '19px' });
const lblOmp = addLabel('ω<sub>p</sub>', V3(), { bold: true, fontSize: '22px' });
const LEAD_ANCHOR = V3(0.25, 2.95, 0.75);
addLabel('τ&#8407; = r&#8407; × <i>M</i>g&#8407;', LEAD_ANCHOR, { fontSize: '18px', bold: true });

/* ── leader curve (rebuilt per frame) ── */
const LEAD_N = 14;
const leadGeom = new THREE.BufferGeometry();
leadGeom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(LEAD_N * 3), 3));
