/* ── leader curve (rebuilt per frame) ── */
const LEAD_N = 14;
const leadGeom = new THREE.BufferGeometry();
leadGeom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(LEAD_N * 3), 3));
const leadLine = new THREE.Line(leadGeom,
