/* ── camera: front-on to the y–z picture plane, figure fills the view ── */
const CAM_ARGS = { projection: 'perspective', azimuthDeg: 14, elevationDeg: 15, rollDeg: 0, heightFraction: 0.8 };
setCameraView(CAM_ARGS);
function maybeRefit() { if (!_userMovedCamera) setCameraView(CAM_ARGS); }

/* ── per-frame: precession, spin loop, moving labels, leader ── */
const clock = new THREE.Clock();
function tick() {
  requestAnimationFrame(tick);
  const dt = Math.min(clock.getDelta(), 0.05);
  if (playing) {
    phi += (tauMag / (L_LEN * Math.sin(theta))) * dt;   // ωp = τ / (L sinθ)
    P.rotation.z = phi;
  }
  loopG.rotation.y += 5 * dt;                            // fast spin about the symmetry axis
  P.updateMatrixWorld(true);

  const cphi = Math.cos(phi), sphi = Math.sin(phi);
  _td.set(-cphi, -sphi, 0);          // world τ / dL tangent direction
  _ro.set(-sphi, cphi, 0);           // world outward radial at L tip
  _cm.copy(S.cmL).applyMatrix4(P.matrixWorld);
  _tip.copy(S.tipL).applyMatrix4(P.matrixWorld);

  lblCM.pos.copy(_cm).add(_t1.set(-0.05, -0.52, 0.3));
  lblR.pos.copy(_cm).multiplyScalar(0.48).add(_t1.set(-0.05, -0.38, 0));
  lblMg.pos.copy(_cm).add(_t1.set(0.02, 0.3, -1.02));
  lblTau.pos.copy(_cm).addScaledVector(_td, S.tauLen + 0.3).add(_t1.set(0, 0, 0.15));
  lblL.pos.lerpVectors(_cm, _tip, 0.6).addScaledVector(_ro, 0.32).add(_t1.set(0, 0, 0.1));
  lblLsin.pos.copy(_t2.set(0, S.R * 0.5, S.H).applyMatrix4(P.matrixWorld)).add(_t1.set(0, 0, 0.24));
  lblDL.pos.copy(_tip).addScaledVector(_td, S.dLLen + 0.42).add(_t1.set(0, 0, 0.12));
  lblDphi.pos.copy(S.dphiPos).applyMatrix4(P.matrixWorld).add(_t1.set(0, 0, 0.04));
  lblOm.pos.copy(T.localToWorld(_t2.set(-0.95, 2.5, 0.15)));

  // leader from the τ = r × Mg label to the τ arrow tip
  _a.copy(LEAD_ANCHOR).add(_t1.set(-0.35, -0.25, 0.2));
  _b.copy(_cm).addScaledVector(_td, S.tauLen * 0.85);
  _ctrl.lerpVectors(_a, _b, 0.5).add(_t1.set(0, 0.35, -0.55));
  leadCurve.v0.copy(_a); leadCurve.v1.copy(_ctrl); leadCurve.v2.copy(_b);
  const arr = leadGeom.attributes.position.array;
  for (let i = 0; i < LEAD_N; i++) {
    const pt = leadCurve.getPoint(i / (LEAD_N - 1));
    arr[i * 3] = pt.x; arr[i * 3 + 1] = pt.y; arr[i * 3 + 2] = pt.z;
  }
  leadGeom.attributes.position.needsUpdate = true;
}
