  rebuild(); maybeRefit();
  document.getElementById('demoTitle').textContent = (demoIdx + 1) + '/' + DEMO.length + ' — ' + st.title;
  document.getElementById('demoNarr').textContent = st.narr;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(demoIdx < 0 ? 0 : demoIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(demoIdx + 1));
