/* ── reactive state + temps ── */
const S = { cmL: V3(), tipL: V3(), dphiPos: V3(), R: 1, H: 3, tauLen: 0.6, dLLen: 0.6 };
const _cm = V3(), _tip = V3(), _td = V3(), _ro = V3(), _t1 = V3(), _t2 = V3(), _a = V3(), _b = V3(), _ctrl = V3();
const leadCurve = new THREE.QuadraticBezierCurve3(V3(), V3(), V3());
const dynRoot = [], dynP = [];
const omOut = document.getElementById('omOut');

/* ── rebuild all θ / τ dependent geometry (physics coords; P must be at identity) ── */
function rebuild() {
  const savedPhi = P.rotation.z;
  P.rotation.z = 0;
  P.updateMatrixWorld(true);
  T.rotation.x = Math.PI / 2 - theta;  // local +Y (symmetry axis) → phys (0, sinθ, cosθ)
  for (const o of dynRoot) { root.remove(o); _disposeObject(o); }
  for (const o of dynP) { P.remove(o); _disposeObject(o); }
  dynRoot.length = 0; dynP.length = 0;

  const sinT = Math.sin(theta), cosT = Math.cos(theta);
  const H = TIP_D * cosT, R = TIP_D * sinT;
  S.H = H; S.R = R;
  S.cmL.set(0, CM_D * sinT, CM_D * cosT);
  S.tipL.set(0, R, H);
  S.tauLen = 0.6 * tauMag;
  S.dLLen = 0.45 * tauMag + 0.15;

  // θ arc at O (in the phys y–z picture plane)
  const thPts = [];
  for (let i = 0; i <= 24; i++) {
    const a = theta * i / 24;
    thPts.push(V3(0, 1.15 * Math.sin(a), 1.15 * Math.cos(a)));
  }
  const thArc = new THREE.Line(new THREE.BufferGeometry().setFromPoints(thPts),
    new THREE.LineBasicMaterial({ color: 0x333333, transparent: true, opacity: 1, depthTest: false }));
  thArc.renderOrder = 9;
  root.add(thArc); dynRoot.push(thArc);
  lblTheta.pos.copy(PW(V3(0, 1.42 * Math.sin(theta / 2) - 0.42, 1.42 * Math.cos(theta / 2))));

  // dashed precession circle (horizontal: constant phys z = H)
  const cPts = [];
  for (let i = 0; i <= 96; i++) {
    const t = Math.PI * 2 * i / 96;
    cPts.push(V3(R * Math.cos(t), R * Math.sin(t), H));
  }
  const circ = new THREE.Line(new THREE.BufferGeometry().setFromPoints(cPts),
    new THREE.LineDashedMaterial({ color: 0x555555, dashSize: 0.22, gapSize: 0.13 }));
  circ.computeLineDistances();
  root.add(circ); dynRoot.push(circ);

  // ωp curved arrow on the left rim (sense = increasing angle, matches animation)
  const a0 = 205 * DEG, a1 = 295 * DEG;
  const wPts = [];
  for (let i = 0; i <= 28; i++) {
    const a = a0 + (a1 - a0) * i / 28;
    wPts.push(V3(R * Math.cos(a), R * Math.sin(a), H + 0.03));
  }
  const omTube = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(wPts), 40, 0.035, 8, false),
    new THREE.MeshBasicMaterial({ color: 0x111111 }));
  const omHead = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.26, 12),
    new THREE.MeshBasicMaterial({ color: 0x111111 }));
  omHead.position.copy(wPts[wPts.length - 1]);
  omHead.quaternion.setFromUnitVectors(UP, V3(-Math.sin(a1), Math.cos(a1), 0));
  root.add(omTube, omHead); dynRoot.push(omTube, omHead);
  lblOmp.pos.copy(PW(V3((R + 0.55) * Math.cos(250 * DEG), (R + 0.55) * Math.sin(250 * DEG), H + 0.12)));

  // persistent arrows
  mgG.position.copy(S.cmL);
  buildArrow(mgG, V3(0, 0, -1), 1.2, 0xcc2222, 0.045, 0.2, 0.12, true);
  buildArrow(tauG, V3(-1, 0, 0), S.tauLen, 0xe8862a, 0.05, 0.18, 0.12, true);
  buildArrow(dlG, V3(-1, 0, 0), S.dLLen, 0xe8862a, 0.04, 0.15, 0.1, true);
  radG.position.set(0, 0, H);
  buildArrow(radG, V3(0, 1, 0), R, 0xe8862a, 0.032, 0.16, 0.1, true);

  // dφ wedge at the circle center (current vs next radial)
  const wR = Math.min(1.1, R * 0.45);
  const w2 = [];
  for (let i = 0; i <= 14; i++) {
    const a = (90 + 26 * i / 14) * DEG;
    w2.push(V3(wR * Math.cos(a), wR * Math.sin(a), H));
  }
  const wedge = new THREE.Line(new THREE.BufferGeometry().setFromPoints(w2),
    new THREE.LineBasicMaterial({ color: 0x333333 }));
  P.add(wedge); dynP.push(wedge);
  S.dphiPos.set((wR + 0.5) * Math.cos(103 * DEG), (wR + 0.5) * Math.sin(103 * DEG), H);

  omOut.innerHTML = 'ω<sub>p</sub> = τ / (L sinθ) = ' + (tauMag / (L_LEN * sinT)).toFixed(2) + ' rad/s';
  P.rotation.z = savedPhi;
  P.updateMatrixWorld(true);
}
rebuild();

/* ── camera: perspective, matches plan; figure fills the view ── */
