/* ── per-frame: precession, spin loop, moving labels, leader ── */
const clock = new THREE.Clock();
function tick() {
  requestAnimationFrame(tick);
  const dt = Math.min(clock.getDelta(), 0.05);
  if (playing) {
    phi += (tauMag / (L_LEN * Math.sin(theta))) * dt;   // ωp = τ / (L sinθ)
    P.rotation.z = phi;
  }
  loopG.rotation.y += 5 * dt;                            // fast spin about the symmetry axis
  P.updateMatrixWorld(true);

  const cphi = Math.cos(phi), sphi = Math.sin(phi);
  _td.set(-cphi, -sphi, 0);          // phys τ / dL tangent direction
  _ro.set(-sphi, cphi, 0);           // phys outward radial at L tip
  _cm.copy(S.cmL).applyMatrix4(P.matrixWorld);   // physics coords (P is inside root)
  _tip.copy(S.tipL).applyMatrix4(P.matrixWorld);

  lblCM.pos.copy(PW(_t1.copy(_cm).add(_t2.set(-0.05, -0.55, 0.32))));
  lblR.pos.copy(PW(_t1.copy(_cm).multiplyScalar(0.45).add(_t2.set(-0.05, -0.42, 0))));
  lblMg.pos.copy(PW(_t1.copy(_cm).add(_t2.set(0.02, 0.3, -1.05))));
  lblTau.pos.copy(PW(_t1.copy(_cm).addScaledVector(_td, S.tauLen + 0.35).add(_t2.set(0, 0, 0.15))));
  lblL.pos.copy(PW(_t1.lerpVectors(_cm, _tip, 0.6).addScaledVector(_ro, 0.35).add(_t2.set(0, 0, 0.1))));
  lblLsin.pos.copy(PW(_t1.set(0, S.R * 0.5, S.H).applyMatrix4(P.matrixWorld).add(_t2.set(0, 0, 0.26))));
  lblDL.pos.copy(PW(_t1.copy(_tip).addScaledVector(_td, S.dLLen + 0.45).add(_t2.set(0, 0, 0.12))));
  lblDphi.pos.copy(PW(_t1.copy(S.dphiPos).applyMatrix4(P.matrixWorld).add(_t2.set(0, 0, 0.05))));
  lblOm.pos.copy(PW(T.localToWorld(_t1.set(-1.05, 3.1, 0.15))));

  // leader from the τ = r × Mg label to the τ arrow tip (world space)
  _a.copy(PW(_t1.copy(LEAD_ANCHOR_P).add(_t2.set(-0.35, -0.25, 0.2))));
  _b.copy(PW(_t1.copy(_cm).addScaledVector(_td, S.tauLen * 0.85)));
  _ctrl.lerpVectors(_a, _b, 0.5);
  _ctrl.y += 0.35;   // bulge in world-up for a graceful curve
  leadCurve.v0.copy(_a); leadCurve.v1.copy(_ctrl); leadCurve.v2.copy(_b);
  const arr = leadGeom.attributes.position.array;
  for (let i = 0; i < LEAD_N; i++) {
    const pt = leadCurve.getPoint(i / (LEAD_N - 1));
    arr[i * 3] = pt.x; arr[i * 3 + 1] = pt.y; arr[i * 3 + 2] = pt.z;
  }
  leadGeom.attributes.position.needsUpdate = true;
}
tick();

